import random

from txn_simulator import Workload
from workloads import WORKLOAD_1, WORKLOAD_2, WORKLOAD_3

# EVOLVE-BLOCK-START

def get_best_schedule(workload, num_seqs):
    """
    Fast internal makespan simulator (longest-path over the conflict DAG)
    enabling 100-1000x more local-search iterations, with oracle fallback.

    1. Parse each txn's ops, build the read/write conflict graph.
    2. Calibrate a weight model (ops-count or unit) against the oracle on
       random sequences; if a model matches exactly, use it as a drop-in
       fast evaluator: fin[t] = max(fin of conflicting predecessors) + w[t].
    3. Massive multi-start greedy + 2-opt/or-opt/reversal local search +
       iterated local search using the fast evaluator.
    4. If calibration fails, fall back to oracle-only search with a
       tuple-keyed cache. Final answer always verified with the oracle.
    """
    import time

    time_budget = 110.0
    start_time = time.time()
    n = workload.num_txns

    oracle_cache = {}

    def oracle(seq):
        k = tuple(seq)
        c = oracle_cache.get(k)
        if c is None:
            c = workload.get_opt_seq_cost(list(seq))
            oracle_cache[k] = c
        return c

    # ---- build internal model ----
    ops_map = None
    for attr in ('workload', 'txns', 'transactions', 'txn_ops', 'ops', 'data'):
        d = getattr(workload, attr, None)
        if isinstance(d, dict) and len(d) >= n:
            ops_map = d
            break

    def key_to_idx(k):
        if isinstance(k, int):
            return k
        s = str(k)
        for p in ('txn', 'transaction_', 't'):
            if s.startswith(p):
                t = s[len(p):]
                if t.isdigit():
                    return int(t)
        try:
            return int(s)
        except Exception:
            return None

    fast = None  # fast(seq) -> cost, or None

    if ops_map is not None:
        txn_ops = {}
        for k, v in ops_map.items():
            i = key_to_idx(k)
            if i is None or not (0 <= i < n):
                continue
            parts = v.split() if isinstance(v, str) else [str(x) for x in v]
            ops = []
            for p in parts:
                if '-' in p:
                    a, b = p.split('-', 1)
                    if a in ('r', 'w'):
                        ops.append((a, b))
            if ops:
                txn_ops[i] = ops
        if len(txn_ops) == n:
            writes = {}
            reads = {}
            for i in range(n):
                for op, key in txn_ops[i]:
                    if op == 'w':
                        writes.setdefault(key, set()).add(i)
                    else:
                        reads.setdefault(key, set()).add(i)
            conflict = [set() for _ in range(n)]
            for key in set(list(writes.keys()) + list(reads.keys())):
                ws = writes.get(key, set())
                grp = ws | reads.get(key, set())
                if ws and len(grp) > 1:
                    for a in grp:
                        conflict[a] |= grp - {a}
            lens = [len(txn_ops[i]) for i in range(n)]

            def make_sur(wts):
                def sur(seq):
                    fin = [-1] * n
                    best = 0
                    for t in seq:
                        s = 0
                        for c in conflict[t]:
                            f = fin[c]
                            if f > s:
                                s = f
                        f = s + wts[t]
                        fin[t] = f
                        if f > best:
                            best = f
                    return best
                return sur

            # calibrate against oracle on random sequences
            rng = random.Random(12345)
            tests = []
            for _ in range(15):
                p = list(range(n))
                rng.shuffle(p)
                tests.append(p)
            for wts in (lens, [1] * n):
                sur = make_sur(wts)
                try:
                    if all(sur(p) == oracle(p) for p in tests):
                        fast = sur
                        break
                except Exception:
                    fast = None

    evalf = fast if fast is not None else oracle

    # ---- search operators (use fast evaluator when available) ----
    def greedy(start_txn, noise=0.0):
        seq = [start_txn]
        remaining = [x for x in range(n) if x != start_txn]
        while remaining:
            scored = []
            for t in remaining:
                c = evalf(seq + [t])
                scored.append((c, random.random() if noise else t, t))
            scored.sort()
            pick = scored[0][2]
            if noise and len(scored) > 1 and random.random() < noise:
                pick = scored[1][2]
            seq.append(pick)
            remaining.remove(pick)
        return evalf(seq), seq

    def local_search(seq, cost):
        improved = True
        while improved and time.time() - start_time < time_budget:
            improved = False
            for i in range(n - 1):
                for j in range(i + 1, n):
                    if time.time() - start_time >= time_budget:
                        return cost, seq
                    seq[i], seq[j] = seq[j], seq[i]
                    c = evalf(seq)
                    if c < cost:
                        cost = c
                        improved = True
                    else:
                        seq[i], seq[j] = seq[j], seq[i]
            for i in range(n):
                if time.time() - start_time >= time_budget:
                    return cost, seq
                t = seq.pop(i)
                for j in range(n):
                    if j == i:
                        continue
                    seq.insert(j, t)
                    c = evalf(seq)
                    if c < cost:
                        cost = c
                        improved = True
                        break
                    seq.pop(j)
                else:
                    seq.insert(i, t)
            for i in range(n - 1):
                for j in range(i + 2, n):
                    if time.time() - start_time >= time_budget:
                        return cost, seq
                    seq[i:j + 1] = seq[i:j + 1][::-1]
                    c = evalf(seq)
                    if c < cost:
                        cost = c
                        improved = True
                    else:
                        seq[i:j + 1] = seq[i:j + 1][::-1]
        return cost, seq

    best_cost = None
    best_seq = None

    # multi-start greedy (cheap with fast evaluator)
    for s in range(n):
        if time.time() - start_time >= time_budget * 0.4:
            break
        c, seq = greedy(s)
        if best_cost is None or c < best_cost:
            best_cost, best_seq = c, seq

    # randomized greedy restarts
    while time.time() - start_time < time_budget * 0.6:
        s = random.randint(0, n - 1)
        c, seq = greedy(s, noise=0.2)
        if best_cost is None or c < best_cost:
            best_cost, best_seq = c, seq

    best_cost, best_seq = local_search(best_seq, best_cost)

    pool = [(best_cost, best_seq)]
    stagnation = 0

    while time.time() - start_time < time_budget:
        base = best_seq if random.random() < 0.5 else random.choice(pool)[1]
        cand = base[:]
        strength = 2 + stagnation // 4
        r = random.random()
        if r < 0.3:
            # ruin-and-recreate: remove a block, greedy reinsertion
            b = random.randint(1, min(6, n))
            i = random.randint(0, n - b)
            removed = cand[i:i + b]
            del cand[i:i + b]
            for t in removed:
                bc, bj = None, 0
                for j in range(len(cand) + 1):
                    cand.insert(j, t)
                    c = evalf(cand)
                    if bc is None or c < bc:
                        bc, bj = c, j
                    cand.pop(j)
                cand.insert(bj, t)
        elif r < 0.7:
            for _ in range(strength):
                i, j = random.sample(range(n), 2)
                cand[i], cand[j] = cand[j], cand[i]
        else:
            i, j = sorted(random.sample(range(n), 2))
            cand[i:j + 1] = cand[i:j + 1][::-1]
        c, cand = local_search(cand, evalf(cand))
        if c < best_cost:
            best_cost, best_seq = c, cand
            stagnation = 0
        else:
            stagnation += 1
        if len(pool) < 6 or c < pool[-1][0]:
            pool.append((c, cand))
            pool.sort(key=lambda x: x[0])
            pool = pool[:6]

    # always verify final answer with the true oracle
    final_cost = workload.get_opt_seq_cost(list(best_seq))
    if final_cost > best_cost and fast is not None:
        # model drifted: re-polish with oracle evaluator as safety net
        evalf = oracle
        best_cost, best_seq = local_search(best_seq, oracle(best_seq))
        final_cost = workload.get_opt_seq_cost(list(best_seq))

    assert len(set(best_seq)) == workload.num_txns
    return final_cost, best_seq

# EVOLVE-BLOCK-END

def get_random_costs():
    workload_size = 100
    workload = Workload(WORKLOAD_1)

    makespan1, schedule1 = get_best_schedule(workload, 10)
    cost1 = workload.get_opt_seq_cost(schedule1)

    workload2 = Workload(WORKLOAD_2)
    makespan2, schedule2 = get_best_schedule(workload2, 10)
    cost2 = workload2.get_opt_seq_cost(schedule2)

    workload3 = Workload(WORKLOAD_3)
    makespan3, schedule3 = get_best_schedule(workload3, 10)
    cost3 = workload3.get_opt_seq_cost(schedule3)
    print(cost1, cost2, cost3)
    return cost1 + cost2 + cost3, [schedule1, schedule2, schedule3]


if __name__ == "__main__":
    makespan, schedule = get_random_costs()
    print(f"Makespan: {makespan}")

